mapper.update:
UPDATE employees
   SET name = #{name}
       , department = #{department, jdbcType=VARCHAR}
       , position = #{position, jdbcType=VARCHAR}
       , phone = #{phone, jdbcType=VARCHAR}
       , birth_date = #{birthDate, jdbcType=VARCHAR}
       , address = #{address, jdbcType=VARCHAR}
       , hire_date = #{hireDate, jdbcType=VARCHAR}
       , resign_date = #{resignDate, jdbcType=VARCHAR}
       , memo = #{memo, jdbcType=VARCHAR}
       , resident_no_enc = #{residentNoEnc, jdbcType=VARCHAR}
 WHERE id = #{id}

UPDATE employees
   SET username = #{username}
       , password_hash = #{passwordHash}
 WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM tb_login_account la
JOIN tb_tenant t ON t.tenant_id = la.tenant_id AND t.tenant_code = #{tenantCode}
WHERE la.login_code = #{id}

mapper.delete:
DELETE FROM tb_login_account la
USING tb_tenant t
WHERE t.tenant_id = la.tenant_id
  AND t.tenant_code = #{tenantCode}
  AND la.login_code = #{id}

mapper.select:
SELECT id AS "id", employee_id AS "employeeId", leave_date AS "leaveDate", days AS "days", note AS "note",
       created_at AS "createdAt", created_by AS "createdBy"
FROM leave_records
WHERE employee_id = #{employeeId}
AND leave_date < #{before}
AND leave_date BETWEEN #{start} AND #{end}
ORDER BY leave_date DESC, id DESC
